import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.FrontierSeedSchedule;

/**
 * Conditionally unbiased fixed-capacity multinomial resampling for Frontier probe inputs.
 *
 * <p>
 * Given entry weights {@code w} with total mass {@code W} and a draw budget {@code m}, entry {@code i} receives
 * {@code k[i]} categorical draws with {@code E[k[i]] = m * w[i] / W}. The reweighted bag {@code k[i] * W / m} is
 * therefore measure-unbiased for the input bag conditional on it, and total mass is preserved exactly on every outcome
 * because the draw counts always sum to {@code m}. Draw randomness derives from the stateless Frontier seed schedule,
 * so identical canonical states resample identically regardless of physical exploration order.
 */
final class FrontierMultinomialResampler {

	private FrontierMultinomialResampler() {
	}

	static int[] drawCounts(double[] weights, int draws, long baseSeed) {
		if (draws < 0) {
			throw new NegativeArraySizeException(Integer.toString(draws));
		}
		double[] cumulative = cumulativeWeights(weights);
		double total = cumulative[cumulative.length - 1];
		int[] counts = new int[weights.length];
		for (int draw = 0; draw < draws; draw++) {
			double unit = unitInterval(FrontierSeedSchedule.derive(
					baseSeed, FrontierRandomDomain.RESAMPLE, 0L, draw));
			counts[categoryFor(cumulative, unit * total)]++;
		}
		return counts;
	}

	static int[] drawCounts(double[] weights, double[] units) {
		double[] cumulative = cumulativeWeights(weights);
		double total = cumulative[cumulative.length - 1];
		int[] counts = new int[weights.length];
		for (double unit : units) {
			if (!(unit >= 0.0d && unit < 1.0d)) {
				throw new IllegalArgumentException("resampling draws must lie in the unit interval");
			}
			counts[categoryFor(cumulative, unit * total)]++;
		}
		return counts;
	}

	private static double[] cumulativeWeights(double[] weights) {
		double[] cumulative = new double[weights.length];
		double total = 0.0d;
		for (int index = 0; index < weights.length; index++) {
			double weight = weights[index];
			if (!Double.isFinite(weight) || weight < 0.0d) {
				throw new IllegalArgumentException("resampled weights must be finite and nonnegative");
			}
			total += weight;
			cumulative[index] = total;
		}
		if (!Double.isFinite(total) || total <= 0.0d) {
			throw new IllegalArgumentException("resampled total mass must be finite and positive");
		}
		return cumulative;
	}

	private static int categoryFor(double[] cumulative, double target) {
		int low = 0;
		int high = cumulative.length - 1;
		while (low < high) {
			int middle = low + high >>> 1;
			if (cumulative[middle] <= target) {
				low = middle + 1;
			} else {
				high = middle;
			}
		}
		return low;
	}

	static double unitInterval(long word) {
		return (word >>> 11) * 0x1.0p-53;
	}
}
